from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility tilting is a strategy that seeks to overweight stocks with lower "
        "volatility. Lower volatility can indicate more stable performance and potentially "
        "less risk, which historically has been associated with better returns."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        symbol_volatility = (
            history.group_by("symbol")
            .agg(
                pl.col("adj_close").std().alias("volatility"),
                (pl.col("adj_close") / pl.col("adj_close").shift(1) - 1.0).alias("return"),
            )
            .sort("volatility", descending=False)
        )

        if symbol_volatility.height < view.symbols.count():
            return Signal(information_available_at=stamp, weights={})

        top_symbols = [symbol for symbol in symbol_volatility["symbol"].to_list()[:5]]
        weight = 1.0 / len(top_symbols)
        return Signal(
            information_available_at=stamp, weights={s: weight for s in top_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
